/* eslint-disable react/no-unstable-nested-components */
/* eslint-disable react-native/no-inline-styles */
import React, {useEffect} from 'react';
import {
  FlatList,
  RefreshControl,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native';
import {Button, Icon, List, Text, Modal, useTheme} from 'react-native-paper';
import {
  IListExamResult,
  formatDateTime,
  useAuthStore,
} from '@smarttestpro/smart-common';
import {useExamResultStore} from '../../stores/dashboard';
import MIcon from 'react-native-vector-icons/MaterialIcons';
import {MainStackParamList} from '../../navigation/MainNavigator';
import {NativeStackScreenProps} from '@react-navigation/native-stack';

type Props = NativeStackScreenProps<MainStackParamList, 'ListExamResultScreen'>;

const ListExamResultScreen = ({navigation, route}: Props) => {
  const [visible, setVisible] = React.useState(false);
  const {user} = useAuthStore();

  const {maDeThi} = route.params;

  const hideModal = () => setVisible(false);
  const {
    listExamResult,
    loadingListExamResult,
    examResultDetail,
    getListExamResult,
    getExamResultDetail,
  } = useExamResultStore();
  const theme = useTheme();

  const onViewExamResultDetail = (maKiemTra: string) => {
    getExamResultDetail(maKiemTra);
    setVisible(true);
  };

  useEffect(() => {
    getListExamResult(user.preferred_username, maDeThi);
  }, [getListExamResult, maDeThi, user.preferred_username]);

  const renderItem = ({item}: {item: IListExamResult}) => (
    <List.Item
      title={item.noiDungDeThi}
      description={
        <View style={{display: 'flex', flexDirection: 'column'}}>
          <View
            style={{
              paddingTop: 8,
              display: 'flex',
              flexDirection: 'row',
              alignItems: 'center',
              gap: 4,
            }}>
            <Icon source="check-circle-outline" size={20} />
            <Text style={{color: theme.colors.secondary}}>
              {item.diem || '-'} điểm
            </Text>
          </View>
          <View
            style={{
              paddingTop: 8,
              display: 'flex',
              flexDirection: 'row',
              alignItems: 'center',
              gap: 4,
            }}>
            <Icon source="calendar-month-outline" size={20} />
            <Text style={{color: theme.colors.secondary}}>
              {formatDateTime(item.ngayKiemTra)}
            </Text>
          </View>
        </View>
      }
      style={{
        borderBottomColor: theme.colors.elevation.level5,
        borderBottomWidth: 1,
      }}
      right={() => (
        <View
          style={{
            paddingTop: 8,
            display: 'flex',
            flexDirection: 'column',
            gap: 8,
          }}>
          <Button
            icon={() => {
              return (
                <MIcon size={20} color="#ffffff" name="format-list-bulleted" />
              );
            }}
            mode="contained"
            onPress={() => {
              navigation.push('WebviewDetailExamResultScreen', {
                testResultId: item.maKiemTra,
              });
            }}>
            Chi tiết
          </Button>
        </View>
      )}
    />
  );

  const renderChiTietKiemTra = ({item}: {item: any}) => (
    <List.Item
      title={item.noiDungDeThi}
      description={
        <View style={{display: 'flex', flexDirection: 'column'}}>
          <View
            style={{
              paddingTop: 8,
              display: 'flex',
              flexDirection: 'row',
              alignItems: 'center',
              gap: 4,
            }}>
            <Text style={{color: theme.colors.secondary}}>
              Câu {item.thuTuCau}:
            </Text>
            <Text style={{color: theme.colors.secondary}}>
              {item.ktStatus === true ? 'Đúng' : 'Sai'}
            </Text>
          </View>
        </View>
      }
      style={{
        borderBottomColor: theme.colors.elevation.level5,
        borderBottomWidth: 1,
      }}
    />
  );
  const containerStyle = {backgroundColor: 'white', padding: 20};

  return (
    <View style={styles.container}>
      <View
        className={`h-10 bg-[${theme.colors.primaryContainer}] flex-row items-center px-2`}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <View className="px-1 h-10 justify-center">
            <MIcon name="arrow-back" size={24} />
          </View>
        </TouchableOpacity>
        <View className="flex-1 items-center mr-2">
          <Text className="text-lg font-bold text-gray-800">
            Kết quả bài thi
          </Text>
        </View>
      </View>
      <View>
        <FlatList
          refreshControl={
            <RefreshControl
              refreshing={loadingListExamResult === 'loading'}
              onRefresh={() => {
                getListExamResult(user.preferred_username, maDeThi);
              }}
            />
          }
          data={listExamResult}
          renderItem={renderItem}
          keyExtractor={item => item.maKiemTra}
        />
      </View>
      <Modal
        visible={visible}
        onDismiss={hideModal}
        contentContainerStyle={containerStyle}>
        <Text>{examResultDetail.tenDeThi}</Text>
        <Text>Điểm: {examResultDetail.diem}</Text>
        <View>
          <FlatList
            data={examResultDetail.danhSachChiTietKiemTra?.sort(
              (a, b) =>
                // eslint-disable-next-line radix
                parseInt(a.thuTuCau || '0') - parseInt(b.thuTuCau || '0'),
            )}
            renderItem={renderChiTietKiemTra}
            keyExtractor={item => item.thuTuCau}
          />
        </View>
      </Modal>
    </View>
  );
};
const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
});

export default ListExamResultScreen;
